//! Emits the Rust source files from the [`Model`].
//!
//! Code is assembled as text, parsed with `syn` (which rejects anything that
//! is not valid Rust before it ever reaches `rustc`) and pretty-printed with
//! `prettyplease`, so the output is deterministic and independent of the
//! local `rustfmt`.

use crate::ir::*;
use std::collections::HashMap;
use std::fmt::Write as _;

pub struct GeneratedFile {
    pub name: &'static str,
    pub contents: String,
}

const HEADER: &str = "\
// @generated by proto-codegen from https://github.com/Mojang/bedrock-protocol-docs
// DO NOT EDIT: run `cargo run --bin proto-codegen` to regenerate this file.

";

/// Rust string literal.
fn lit(text: &str) -> String {
    format!("{text:?}")
}

/// `#[doc]` attributes for free text coming from the schemas. Lines are
/// trimmed so that Markdown never sees an indented block (rustdoc would
/// compile it as a doctest), and the characters rustdoc interprets are escaped.
fn doc_attrs(text: Option<&str>) -> String {
    let Some(text) = text else { return String::new() };
    let mut out = String::new();
    for line in text.trim().lines() {
        let mut clean = String::new();
        // A code fence would be compiled as a doctest.
        for c in line.trim().replace("```", "'''").chars() {
            match c {
                '[' | ']' | '<' | '>' | '\\' => {
                    clean.push('\\');
                    clean.push(c);
                }
                '\t' => clean.push(' '),
                _ => clean.push(c),
            }
        }
        let _ = writeln!(out, "#[doc = {}]", lit(&format!(" {clean}")));
    }
    out
}

fn doc_lines(parts: &[Option<String>]) -> String {
    let mut out = String::new();
    let mut first = true;
    for part in parts.iter().flatten() {
        if part.trim().is_empty() {
            continue;
        }
        if !first {
            out.push_str("#[doc = \"\"]\n");
        }
        first = false;
        out.push_str(&doc_attrs(Some(part)));
    }
    out
}

/// Raw documentation line, for text written by the generator itself.
fn raw_doc(text: &str) -> String {
    format!("#[doc = {}]\n", lit(&format!(" {text}")))
}

/// Turns an expression of type `&T` into one of type `T` (for `Copy` values).
fn deref(expr: &str) -> String {
    match expr.strip_prefix('&') {
        Some(place) if !place.starts_with('&') => place.to_owned(),
        _ => format!("*{expr}"),
    }
}

fn format_file(source: &str, name: &str) -> Result<String, String> {
    let file = syn::parse_file(source).map_err(|e| {
        let line = e.span().start().line;
        let context = source.lines().nth(line.saturating_sub(1)).unwrap_or("");
        format!("internal error: generated {name} is not valid Rust: {e} (line {line}: {context})")
    })?;
    Ok(format!("{HEADER}{}", prettyplease::unparse(&file)))
}

pub struct Emitter<'m> {
    model: &'m Model,
    /// Alias name -> Rust type it stands for.
    alias_types: HashMap<&'m str, String>,
    structs: HashMap<&'m str, &'m StructDef>,
    upstream_commit: Option<String>,
}

impl<'m> Emitter<'m> {
    pub fn new(model: &'m Model, upstream_commit: Option<String>) -> Self {
        let mut emitter = Self {
            model,
            alias_types: HashMap::new(),
            structs: model.structs.iter().map(|def| (def.name.as_str(), def)).collect(),
            upstream_commit,
        };
        let alias_types = model.aliases.iter().map(|def| (def.name.as_str(), emitter.rust_type(&def.ty))).collect();
        emitter.alias_types = alias_types;
        emitter
    }

    pub fn emit(&self) -> Result<Vec<GeneratedFile>, String> {
        Ok(vec![
            GeneratedFile { name: "mod.rs", contents: format_file(&self.module(), "mod.rs")? },
            GeneratedFile { name: "enums.rs", contents: format_file(&self.enums(), "enums.rs")? },
            GeneratedFile { name: "types.rs", contents: format_file(&self.types(), "types.rs")? },
            GeneratedFile { name: "packets.rs", contents: format_file(&self.packets(), "packets.rs")? },
            GeneratedFile { name: "samples.rs", contents: format_file(&self.samples(), "samples.rs")? },
        ])
    }

    // ------------------------------------------------------------------ types

    fn rust_type(&self, ty: &Ty) -> String {
        match ty {
            Ty::Bool => "bool".into(),
            Ty::Int(int, _) => int.rust().into(),
            Ty::F32 => "f32".into(),
            Ty::F64 => "f64".into(),
            Ty::String => "String".into(),
            Ty::Nbt => "NetworkNbt".into(),
            Ty::Unit => "()".into(),
            Ty::Named(name) => name.clone(),
            Ty::Enum { name, allow_unknown: true, .. } => format!("MaybeUnknown<{name}>"),
            Ty::Enum { name, .. } => name.clone(),
            Ty::Alias { name, target } => {
                // Use-site options can change the Rust type of the target (an
                // enum that tolerates unknown values); only name the alias
                // when it still denotes the same type.
                let target = self.rust_type(target);
                match self.alias_types.get(name.as_str()) {
                    Some(declared) if *declared != target => target,
                    _ => name.clone(),
                }
            }
            Ty::Option(inner) => format!("Option<{}>", self.rust_type(inner)),
            Ty::Vec(inner, _) | Ty::FixedVec(inner, _) => format!("Vec<{}>", self.rust_type(inner)),
            Ty::Array(inner, len) => format!("[{}; {len}]", self.rust_type(inner)),
            Ty::Map(key, value) => format!("Vec<({}, {})>", self.rust_type(key), self.rust_type(value)),
            Ty::Boxed(inner) => format!("Box<{}>", self.rust_type(inner)),
        }
    }

    /// Statements writing the value behind `expr` (an expression of type `&T`).
    fn ser(&self, ty: &Ty, expr: &str, depth: usize) -> String {
        match ty {
            Ty::Bool => format!("codec::put_bool(buf, {});", deref(expr)),
            Ty::Int(int, enc) => format!("codec::put_{}(buf, {});", int_fn_suffix(*int, *enc), deref(expr)),
            Ty::F32 => format!("codec::put_f32_le(buf, {});", deref(expr)),
            Ty::F64 => format!("codec::put_f64_le(buf, {});", deref(expr)),
            Ty::String => format!("codec::put_string(buf, {expr})?;"),
            Ty::Nbt | Ty::Named(_) => format!("BedrockCodec::serialize({expr}, buf)?;"),
            Ty::Unit => String::new(),
            Ty::Enum { wire: EnumWire::Raw(int, enc), .. } => format!(
                "codec::put_{}(buf, ({}).to_raw() as {});",
                int_fn_suffix(*int, *enc),
                deref(expr),
                int.rust()
            ),
            Ty::Enum { wire: EnumWire::Name, .. } => {
                format!("codec::put_string(buf, &({}).wire_name())?;", deref(expr))
            }
            Ty::Alias { target, .. } => self.ser(target, expr, depth),
            Ty::Option(inner) => {
                let var = format!("v{depth}");
                format!(
                    "match {expr} {{ Some({var}) => {{ codec::put_bool(buf, true); {} }} None => codec::put_bool(buf, false), }}",
                    self.ser(inner, &var, depth + 1)
                )
            }
            Ty::Vec(inner, len) => {
                let var = format!("v{depth}");
                let put_len = match len {
                    LenEnc::Var => "put_len_var",
                    LenEnc::U32Le => "put_len_u32_le",
                };
                format!(
                    "codec::{put_len}(buf, ({expr}).len())?; for {var} in ({expr}).iter() {{ {} }}",
                    self.ser(inner, &var, depth + 1)
                )
            }
            Ty::FixedVec(inner, len) => {
                let var = format!("v{depth}");
                format!(
                    "codec::check_len(({expr}).len(), {len})?; for {var} in ({expr}).iter() {{ {} }}",
                    self.ser(inner, &var, depth + 1)
                )
            }
            Ty::Array(inner, _) => {
                let var = format!("v{depth}");
                format!("for {var} in ({expr}).iter() {{ {} }}", self.ser(inner, &var, depth + 1))
            }
            Ty::Map(key, value) => {
                let (k, v) = (format!("k{depth}"), format!("v{depth}"));
                format!(
                    "codec::put_len_var(buf, ({expr}).len())?; for ({k}, {v}) in ({expr}).iter() {{ {} {} }}",
                    self.ser(key, &k, depth + 1),
                    self.ser(value, &v, depth + 1)
                )
            }
            Ty::Boxed(inner) => self.ser(inner, &format!("&**({expr})"), depth),
        }
    }

    /// Expression reading a value of type `ty` from `buf`.
    fn de(&self, ty: &Ty) -> String {
        match ty {
            Ty::Bool => "codec::get_bool(buf)?".into(),
            Ty::Int(int, enc) => format!("codec::get_{}(buf)?", int_fn_suffix(*int, *enc)),
            Ty::F32 => "codec::get_f32_le(buf)?".into(),
            Ty::F64 => "codec::get_f64_le(buf)?".into(),
            Ty::String => "codec::get_string(buf)?".into(),
            Ty::Nbt => "<NetworkNbt as BedrockCodec>::deserialize(buf)?".into(),
            Ty::Named(name) => format!("<{name} as BedrockCodec>::deserialize(buf)?"),
            Ty::Unit => "()".into(),
            Ty::Enum { name, wire: EnumWire::Raw(int, enc), allow_unknown } => {
                let raw = format!("codec::get_{}(buf)? as i64", int_fn_suffix(*int, *enc));
                if *allow_unknown {
                    format!("MaybeUnknown::<{name}>::from_raw({raw})")
                } else {
                    format!("<{name} as ProtocolEnum>::from_wire({raw})?")
                }
            }
            Ty::Enum { name, wire: EnumWire::Name, .. } => {
                format!("<{name} as ProtocolEnum>::from_wire_name(&codec::get_string(buf)?)?")
            }
            Ty::Alias { target, .. } => self.de(target),
            Ty::Option(inner) => format!("if codec::get_bool(buf)? {{ Some({}) }} else {{ None }}", self.de(inner)),
            Ty::Vec(inner, len) => {
                let get_len = match len {
                    LenEnc::Var => "get_len_var",
                    LenEnc::U32Le => "get_len_u32_le",
                };
                format!(
                    "{{ let len = codec::{get_len}(buf)?; codec::get_vec(buf, len, |buf| Ok({}))? }}",
                    self.de(inner)
                )
            }
            Ty::FixedVec(inner, len) => format!("codec::get_vec(buf, {len}, |buf| Ok({}))?", self.de(inner)),
            Ty::Array(inner, _) => format!("codec::get_array(buf, |buf| Ok({}))?", self.de(inner)),
            Ty::Map(key, value) => format!(
                "{{ let len = codec::get_len_var(buf)?; codec::get_vec(buf, len, |buf| Ok(({}, {})))? }}",
                self.de(key),
                self.de(value)
            ),
            Ty::Boxed(inner) => format!("Box::new({})", self.de(inner)),
        }
    }

    /// Expression building a pseudo-random value of type `ty` (tests only).
    fn sample(&self, ty: &Ty) -> String {
        match ty {
            Ty::Bool | Ty::Int(..) | Ty::F32 | Ty::F64 | Ty::String | Ty::Nbt | Ty::Named(_) => {
                "Sample::sample(g)".into()
            }
            Ty::Unit => "()".into(),
            Ty::Enum { allow_unknown: true, .. } => "MaybeUnknown::Known(Sample::sample(g))".into(),
            Ty::Enum { .. } => "Sample::sample(g)".into(),
            Ty::Alias { target, .. } => self.sample(target),
            Ty::Option(inner) => format!("g.option(|g| {})", self.sample(inner)),
            Ty::Vec(inner, _) => format!("g.vec(|g| {})", self.sample(inner)),
            Ty::FixedVec(inner, len) => format!("g.vec_of({len}, |g| {})", self.sample(inner)),
            Ty::Array(inner, _) => format!("std::array::from_fn(|_| {})", self.sample(inner)),
            Ty::Map(key, value) => format!("g.vec(|g| ({}, {}))", self.sample(key), self.sample(value)),
            Ty::Boxed(inner) => format!("Box::new({})", self.sample(inner)),
        }
    }

    // ------------------------------------------------------------------ mod.rs

    fn module(&self) -> String {
        let model = self.model;
        let mut out = String::new();
        out.push_str(
            "//! Protocol definitions generated from Mojang's `bedrock-protocol-docs`.\n\
             //!\n\
             //! * [`enums`]: protocol enums;\n\
             //! * [`types`]: structures, variants and aliases;\n\
             //! * [`packets`]: one struct per packet and the [`packets::Packet`] dispatch enum.\n\n\
             pub mod enums;\npub mod packets;\npub mod types;\n\n#[cfg(test)]\nmod samples;\n\n",
        );
        let _ = writeln!(
            out,
            "{}pub const PROTOCOL_VERSION: i32 = {};",
            raw_doc("Network protocol version described by the schemas."),
            model.protocol_version
        );
        let _ = writeln!(
            out,
            "{}pub const MINECRAFT_VERSION: &str = {};",
            raw_doc("Game version described by the schemas."),
            lit(&model.minecraft_version)
        );
        let _ = writeln!(
            out,
            "{}pub const MOJANG_DOCS_COMMIT: &str = {};",
            raw_doc("Commit of `Mojang/bedrock-protocol-docs` the code was generated from."),
            lit(self.upstream_commit.as_deref().unwrap_or("unknown"))
        );
        let _ = writeln!(
            out,
            "{}pub const PACKET_COUNT: usize = {};",
            raw_doc("Number of packets in the protocol."),
            model.packets.len()
        );
        out.push_str(MODULE_TESTS);
        out
    }

    // ---------------------------------------------------------------- enums.rs

    fn enums(&self) -> String {
        let mut out = String::from(
            "//! Protocol enums.\n\
             //!\n\
             //! C++ enumerators sharing a value with an earlier one are exposed as\n\
             //! associated constants (`Enum::Alias`) since Rust discriminants are unique.\n\
             #![allow(non_upper_case_globals, clippy::all)]\n\n\
             use crate::codec::{ProtocolEnum, ProtocolError};\n\n",
        );
        for def in &self.model.enums {
            self.enum_def(&mut out, def);
        }
        out
    }

    fn enum_def(&self, out: &mut String, def: &EnumDef) {
        let name = &def.name;
        let repr = def.repr.rust();
        let source = lit(&def.source);

        out.push_str(&doc_lines(&[def.doc.clone(), Some(format!("Protocol enum {}.", def.source))]));
        let _ = writeln!(out, "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]\npub enum {name} {{");
        // Default to the zero value when the enum has one.
        let default_index = def.variants.iter().position(|variant| variant.value == 0).unwrap_or(0);
        for (index, variant) in def.variants.iter().enumerate() {
            out.push_str(&doc_lines(&[
                variant.doc.clone(),
                Some(format!("{} = {}", variant.original, variant.value)),
            ]));
            if index == default_index {
                out.push_str("#[default]\n");
            }
            let _ = writeln!(out, "{},", variant.name);
        }
        out.push_str("}\n");

        let _ = writeln!(out, "impl {name} {{");
        out.push_str(&raw_doc("Every variant, in declaration order."));
        let all: Vec<String> = def.variants.iter().map(|v| format!("Self::{}", v.name)).collect();
        let _ = writeln!(out, "pub const ALL: &'static [Self] = &[{}];", all.join(", "));
        for alias in &def.aliases {
            out.push_str(&doc_lines(&[
                alias.doc.clone(),
                Some(format!("{}: same value as {}.", alias.original, alias.target)),
            ]));
            let _ = writeln!(out, "pub const {}: Self = Self::{};", alias.name, alias.target);
        }
        out.push_str(&raw_doc("Numeric value of the variant."));
        let _ = writeln!(out, "pub const fn value(self) -> {repr} {{ match self {{");
        for variant in &def.variants {
            let _ = writeln!(out, "Self::{} => {},", variant.name, variant.value);
        }
        out.push_str("} }\n");
        out.push_str(&raw_doc("Variant holding this numeric value, if any."));
        let _ = writeln!(out, "pub const fn from_value(value: {repr}) -> Option<Self> {{ match value {{");
        for variant in &def.variants {
            let _ = writeln!(out, "{} => Some(Self::{}),", variant.value, variant.name);
        }
        out.push_str("_ => None, } }\n}\n");

        let _ = writeln!(out, "impl ProtocolEnum for {name} {{\nconst NAME: &'static str = {source};");
        out.push_str("fn to_raw(self) -> i64 { self.value() as i64 }\n");
        let _ = writeln!(
            out,
            "fn from_raw(raw: i64) -> Option<Self> {{ <{repr}>::try_from(raw).ok().and_then(Self::from_value) }}"
        );
        out.push_str("fn name(self) -> &'static str { match self {\n");
        for variant in &def.variants {
            let _ = writeln!(out, "Self::{} => {},", variant.name, lit(&variant.original));
        }
        out.push_str("} }\n");
        let mut names: Vec<String> =
            def.variants.iter().map(|v| format!("({}, {name}::{})", lit(&v.original), v.name)).collect();
        names.extend(def.aliases.iter().map(|a| format!("({}, {name}::{})", lit(&a.original), a.target)));
        let _ = writeln!(
            out,
            "fn from_name(name: &str) -> Option<Self> {{\n\
             const NAMES: &[(&str, {name})] = &[{}];\n\
             NAMES.iter().find(|(candidate, _)| *candidate == name)\n\
             .or_else(|| NAMES.iter().find(|(candidate, _)| candidate.eq_ignore_ascii_case(name)))\n\
             .map(|(_, value)| *value)\n}}\n}}",
            names.join(", ")
        );

        let _ = writeln!(out, "impl From<{name}> for {repr} {{ fn from(value: {name}) -> Self {{ value.value() }} }}");
        let _ = writeln!(
            out,
            "impl TryFrom<{repr}> for {name} {{\ntype Error = ProtocolError;\n\
             fn try_from(value: {repr}) -> Result<Self, ProtocolError> {{\n\
             Self::from_value(value).ok_or(ProtocolError::InvalidEnumValue {{ enum_name: {source}, value: value as i64 }})\n\
             }}\n}}\n"
        );
    }

    // ---------------------------------------------------------------- types.rs

    fn types(&self) -> String {
        let mut out = String::from(
            "//! Protocol structures, variants (`oneOf`) and aliases.\n\
             #![allow(unused_variables, unused_imports, clippy::all)]\n\n\
             use super::enums::*;\n\
             use crate::codec::{self, BedrockCodec, Buf, BufMut, MaybeUnknown, NetworkNbt, ProtocolEnum, ProtocolError, Result};\n\n",
        );
        for def in &self.model.aliases {
            out.push_str(&doc_lines(&[def.doc.clone(), Some(format!("Protocol type {}.", def.source))]));
            let _ = writeln!(out, "pub type {} = {};\n", def.name, self.rust_type(&def.ty));
        }
        for def in &self.model.structs {
            self.struct_def(&mut out, def);
        }
        for def in &self.model.variants {
            self.variant_def(&mut out, def);
        }
        out
    }

    fn field_ser(&self, field: &Field) -> String {
        match &field.constant {
            Some(constant) => self.ser(&field.ty, &format!("&Self::{}", constant.const_name), 0),
            None => self.ser(&field.ty, &format!("&self.{}", field.name), 0),
        }
    }

    /// Statement reading a constant field and failing unless it holds its value.
    fn const_check(&self, def: &StructDef, field: &Field, constant: &ConstValue) -> String {
        format!(
            "{{ let found = {}; if found != Self::{c} {{ return Err(ProtocolError::UnexpectedTag {{ \
             type_name: {}, expected: ProtocolEnum::to_raw(Self::{c}), found: ProtocolEnum::to_raw(found) }}); }} }}\n",
            self.de(&field.ty),
            lit(&def.source),
            c = constant.const_name
        )
    }

    /// Statements reading `fields`; stored fields are bound to `f<index>`.
    fn fields_de(&self, def: &StructDef, fields: &[(usize, &Field)]) -> String {
        let mut out = String::new();
        for (index, field) in fields {
            match &field.constant {
                Some(constant) => out.push_str(&self.const_check(def, field, constant)),
                None => {
                    let _ = writeln!(out, "let f{index} = {};", self.de(&field.ty));
                }
            }
        }
        let init: Vec<String> = fields
            .iter()
            .filter(|(_, field)| field.constant.is_none())
            .map(|(index, field)| format!("{}: f{index}", field.name))
            .collect();
        let _ = writeln!(out, "Ok(Self {{ {} }})", init.join(", "));
        out
    }

    fn struct_def(&self, out: &mut String, def: &StructDef) {
        let name = &def.name;
        out.push_str(&doc_lines(&[def.doc.clone(), Some(format!("Protocol type {}.", def.source))]));
        let _ = writeln!(out, "#[derive(Debug, Clone, PartialEq, Default)]\npub struct {name} {{");
        for field in def.fields.iter().filter(|field| field.constant.is_none()) {
            out.push_str(&doc_lines(&[field.doc.clone(), Some(format!("Documented as \"{}\".", field.original))]));
            let _ = writeln!(out, "pub {}: {},", field.name, self.rust_type(&field.ty));
        }
        out.push_str("}\n");

        let indexed: Vec<(usize, &Field)> = def.fields.iter().enumerate().collect();
        let has_tag = def.tag().is_some();
        let consts: Vec<&Field> = def.fields.iter().filter(|field| field.constant.is_some()).collect();
        if !consts.is_empty() {
            let _ = writeln!(out, "impl {name} {{");
            for field in &consts {
                let constant = field.constant.as_ref().expect("filtered on constants");
                out.push_str(&doc_lines(&[
                    field.doc.clone(),
                    Some(format!("Constant value of the {} field.", field.original)),
                ]));
                let _ = writeln!(
                    out,
                    "pub const {}: {} = {}::{};",
                    constant.const_name, constant.enum_name, constant.enum_name, constant.variant
                );
            }
            if has_tag {
                out.push_str(&raw_doc("Writes the fields that follow the leading discriminator."));
                out.push_str("pub fn serialize_body<B: BufMut>(&self, buf: &mut B) -> Result<()> {\n");
                for field in &def.fields[1..] {
                    out.push_str(&self.field_ser(field));
                    out.push('\n');
                }
                out.push_str("Ok(())\n}\n");
                out.push_str(&raw_doc("Reads the fields that follow the leading discriminator."));
                out.push_str("pub fn deserialize_body<B: Buf>(buf: &mut B) -> Result<Self> {\n");
                out.push_str(&self.fields_de(def, &indexed[1..]));
                out.push_str("}\n");
            }
            out.push_str("}\n");
        }

        let _ = writeln!(out, "impl BedrockCodec for {name} {{");
        out.push_str("fn serialize<B: BufMut>(&self, buf: &mut B) -> Result<()> {\n");
        if has_tag {
            out.push_str(&self.field_ser(&def.fields[0]));
            out.push_str("\nself.serialize_body(buf)\n}\n");
        } else {
            for field in &def.fields {
                out.push_str(&self.field_ser(field));
                out.push('\n');
            }
            out.push_str("Ok(())\n}\n");
        }
        out.push_str("fn deserialize<B: Buf>(buf: &mut B) -> Result<Self> {\n");
        if has_tag {
            let tag = &def.fields[0];
            let constant = tag.constant.as_ref().expect("a tag is a constant field");
            out.push_str(&self.const_check(def, tag, constant));
            out.push_str("Self::deserialize_body(buf)\n}\n");
        } else {
            out.push_str(&self.fields_de(def, &indexed));
            out.push_str("}\n");
        }
        out.push_str("}\n\n");
    }

    /// Name of the struct behind a tagged branch.
    fn branch_struct<'a>(&self, ty: &'a Ty) -> Option<(&'a str, bool)> {
        match ty {
            Ty::Named(name) if self.structs.contains_key(name.as_str()) => Some((name, false)),
            Ty::Boxed(inner) => self.branch_struct(inner).map(|(name, _)| (name, true)),
            _ => None,
        }
    }

    fn variant_def(&self, out: &mut String, def: &VariantDef) {
        let name = &def.name;
        let source = lit(&def.source);
        let encoding = match &def.kind {
            VariantKind::Index(..) => "Encoded as the index of the active branch followed by the branch.",
            VariantKind::Tagged { .. } => "Discriminated by the leading constant field of each branch.",
        };
        out.push_str(&doc_lines(&[
            def.doc.clone(),
            Some(format!("Protocol variant {}.", def.source)),
            Some(encoding.to_owned()),
        ]));
        let _ = writeln!(out, "#[derive(Debug, Clone, PartialEq)]\npub enum {name} {{");
        for branch in &def.branches {
            match &branch.ty {
                Ty::Unit => {
                    let _ = writeln!(out, "{},", branch.name);
                }
                ty => {
                    let _ = writeln!(out, "{}({}),", branch.name, self.rust_type(ty));
                }
            }
        }
        out.push_str("}\n");

        // Default: an empty branch if there is one, else the first branch
        // that is not part of a recursion.
        let default = def
            .branches
            .iter()
            .find(|branch| branch.ty == Ty::Unit)
            .or_else(|| def.branches.iter().find(|branch| !matches!(branch.ty, Ty::Boxed(_))))
            .unwrap_or(&def.branches[0]);
        let default_expr = match default.ty {
            Ty::Unit => format!("Self::{}", default.name),
            _ => format!("Self::{}(Default::default())", default.name),
        };
        let _ = writeln!(out, "impl Default for {name} {{ fn default() -> Self {{ {default_expr} }} }}");

        let _ = writeln!(out, "impl BedrockCodec for {name} {{");
        out.push_str("fn serialize<B: BufMut>(&self, buf: &mut B) -> Result<()> {\nmatch self {\n");
        for (index, branch) in def.branches.iter().enumerate() {
            let prefix = match &def.kind {
                VariantKind::Index(int, enc) => format!("codec::put_{}(buf, {index});", int_fn_suffix(*int, *enc)),
                // The branch struct writes its own discriminator.
                VariantKind::Tagged { .. } => String::new(),
            };
            match &branch.ty {
                Ty::Unit => {
                    let _ = writeln!(out, "Self::{} => {{ {prefix} }}", branch.name);
                }
                ty => {
                    let _ = writeln!(out, "Self::{}(v) => {{ {prefix} {} }}", branch.name, self.ser(ty, "v", 0));
                }
            }
        }
        out.push_str("}\nOk(())\n}\n");

        out.push_str("fn deserialize<B: Buf>(buf: &mut B) -> Result<Self> {\n");
        match &def.kind {
            VariantKind::Index(int, enc) => {
                let _ = writeln!(out, "match codec::get_{}(buf)? {{", int_fn_suffix(*int, *enc));
                for (index, branch) in def.branches.iter().enumerate() {
                    match &branch.ty {
                        Ty::Unit => {
                            let _ = writeln!(out, "{index} => Ok(Self::{}),", branch.name);
                        }
                        ty => {
                            let _ = writeln!(out, "{index} => Ok(Self::{}({})),", branch.name, self.de(ty));
                        }
                    }
                }
                let _ = writeln!(
                    out,
                    "other => Err(ProtocolError::InvalidVariantIndex {{ type_name: {source}, index: other as i64 }}),\n}}"
                );
            }
            VariantKind::Tagged { tag } => {
                let Ty::Enum { name: enum_name, .. } = tag else { unreachable!("tags are enums") };
                let _ = writeln!(out, "let tag = {};", self.de(tag));
                for branch in &def.branches {
                    let (struct_name, boxed) = self.branch_struct(&branch.ty).expect("tagged branches are structs");
                    let variant = branch.tag_variant.as_ref().expect("tagged branches carry their tag");
                    let body = format!("{struct_name}::deserialize_body(buf)?");
                    let body = if boxed { format!("Box::new({body})") } else { body };
                    let _ = writeln!(
                        out,
                        "if tag == {enum_name}::{variant} {{ return Ok(Self::{}({body})); }}",
                        branch.name
                    );
                }
                let _ = writeln!(
                    out,
                    "Err(ProtocolError::InvalidVariantIndex {{ type_name: {source}, index: ProtocolEnum::to_raw(tag) }})"
                );
            }
        }
        out.push_str("}\n}\n\n");
    }

    // -------------------------------------------------------------- packets.rs

    fn packets(&self) -> String {
        let packets = &self.model.packets;
        let mut out = String::from(
            "//! Packets and the global [`Packet`] dispatch table.\n\
             #![allow(unused_variables, unused_imports, clippy::all)]\n\n\
             use super::enums::*;\n\
             use super::types::*;\n\
             use crate::codec::{self, BedrockCodec, Buf, BufMut, MaybeUnknown, NetworkNbt, ProtocolEnum, ProtocolError, Result};\n\n",
        );

        for packet in packets {
            let name = &packet.name;
            out.push_str(&doc_lines(&[packet.doc.clone(), Some(format!("Packet {} (id {}).", packet.source, packet.id))]));
            let _ = writeln!(
                out,
                "#[derive(Debug, Clone, PartialEq, Default)]\npub struct {name} {{ pub payload: {} }}",
                self.rust_type(&packet.payload)
            );
            let _ = writeln!(
                out,
                "impl {name} {{\n{}pub const ID: u32 = {};\n{}pub const NAME: &'static str = {};\n}}",
                raw_doc("Official packet identifier."),
                packet.id,
                raw_doc("Official packet name."),
                lit(&packet.source)
            );
            let _ = writeln!(
                out,
                "impl BedrockCodec for {name} {{\n\
                 fn serialize<B: BufMut>(&self, buf: &mut B) -> Result<()> {{ {} Ok(()) }}\n\
                 fn deserialize<B: Buf>(buf: &mut B) -> Result<Self> {{ Ok(Self {{ payload: {} }}) }}\n}}",
                self.ser(&packet.payload, "&self.payload", 0),
                self.de(&packet.payload)
            );
            let _ = writeln!(
                out,
                "impl From<{name}> for Packet {{ fn from(packet: {name}) -> Self {{ Packet::{}(packet) }} }}\n",
                packet.variant
            );
        }

        out.push_str(&raw_doc("Every packet of the protocol, keyed by its official identifier."));
        out.push_str("#[derive(Debug, Clone, PartialEq)]\npub enum Packet {\n");
        for packet in packets {
            let _ = writeln!(out, "{}{}({}),", raw_doc(&format!("Id {}.", packet.id)), packet.variant, packet.name);
        }
        out.push_str("}\n\nimpl Packet {\n");

        out.push_str(&raw_doc("Identifiers of every known packet, in ascending order."));
        let ids: Vec<String> = packets.iter().map(|p| format!("{}::ID", p.name)).collect();
        let _ = writeln!(out, "pub const IDS: &'static [u32] = &[{}];", ids.join(", "));

        out.push_str(&raw_doc("Official identifier of the packet."));
        out.push_str("pub fn packet_id(&self) -> u32 { match self {\n");
        for packet in packets {
            let _ = writeln!(out, "Self::{}(_) => {}::ID,", packet.variant, packet.name);
        }
        out.push_str("} }\n");

        out.push_str(&raw_doc("Official name of the packet."));
        out.push_str("pub fn name(&self) -> &'static str { match self {\n");
        for packet in packets {
            let _ = writeln!(out, "Self::{}(_) => {}::NAME,", packet.variant, packet.name);
        }
        out.push_str("} }\n");

        out.push_str(&raw_doc("Official name of the packet with this identifier, if it exists."));
        out.push_str("pub fn name_of(packet_id: u32) -> Option<&'static str> { match packet_id {\n");
        for packet in packets {
            let _ = writeln!(out, "{0}::ID => Some({0}::NAME),", packet.name);
        }
        out.push_str("_ => None,\n} }\n");

        out.push_str(&raw_doc("Writes the packet body (without the packet header)."));
        out.push_str("pub fn encode<B: BufMut>(&self, buf: &mut B) -> Result<()> { match self {\n");
        for packet in packets {
            let _ = writeln!(out, "Self::{}(packet) => BedrockCodec::serialize(packet, buf),", packet.variant);
        }
        out.push_str("} }\n");

        out.push_str(&raw_doc("Reads the body of the packet identified by `packet_id`."));
        out.push_str("pub fn decode<B: Buf>(packet_id: u32, buf: &mut B) -> Result<Self> { match packet_id {\n");
        for packet in packets {
            let _ = writeln!(
                out,
                "{}::ID => Ok(Self::{}(BedrockCodec::deserialize(buf)?)),",
                packet.name, packet.variant
            );
        }
        out.push_str("other => Err(ProtocolError::UnknownPacketId(other)),\n} }\n");

        out.push_str(&raw_doc("Default-initialized packet for this identifier, if it exists."));
        out.push_str("pub fn default_for_id(packet_id: u32) -> Option<Self> { match packet_id {\n");
        for packet in packets {
            let _ = writeln!(out, "{}::ID => Some(Self::{}(Default::default())),", packet.name, packet.variant);
        }
        out.push_str("_ => None,\n} }\n");

        out.push_str(&raw_doc("Writes the packet header (identifier, no sub-client) followed by the body."));
        out.push_str(
            "pub fn encode_with_header<B: BufMut>(&self, buf: &mut B) -> Result<()> {\n\
             BedrockCodec::serialize(&codec::PacketHeader::new(self.packet_id()), buf)?;\n\
             self.encode(buf)\n}\n",
        );
        out.push_str(&raw_doc("Reads a packet header, then the body it announces."));
        out.push_str(
            "pub fn decode_with_header<B: Buf>(buf: &mut B) -> Result<(codec::PacketHeader, Self)> {\n\
             let header = <codec::PacketHeader as BedrockCodec>::deserialize(buf)?;\n\
             let packet = Self::decode(header.packet_id, buf)?;\n\
             Ok((header, packet))\n}\n",
        );
        out.push_str("}\n");
        out
    }

    // -------------------------------------------------------------- samples.rs

    fn samples(&self) -> String {
        let model = self.model;
        let mut out = String::from(
            "//! Pseudo-random value builders used by the round-trip tests.\n\
             #![allow(unused_variables, unused_imports, clippy::all)]\n\n\
             use super::enums::*;\n\
             use super::packets::*;\n\
             use super::types::*;\n\
             use crate::codec::{MaybeUnknown, NetworkNbt};\n\
             use crate::testing::{Gen, Sample};\n\n",
        );
        for def in &model.enums {
            let _ = writeln!(
                out,
                "impl Sample for {} {{ fn sample(g: &mut Gen) -> Self {{ Self::ALL[g.below(Self::ALL.len())] }} }}",
                def.name
            );
        }
        for def in &model.structs {
            let fields: Vec<String> = def
                .fields
                .iter()
                .filter(|field| field.constant.is_none())
                .map(|field| format!("{}: {}", field.name, self.sample(&field.ty)))
                .collect();
            let _ = writeln!(
                out,
                "impl Sample for {} {{ fn sample(g: &mut Gen) -> Self {{ Self {{ {} }} }} }}",
                def.name,
                fields.join(", ")
            );
        }
        for def in &model.variants {
            let _ = writeln!(
                out,
                "impl Sample for {} {{ fn sample(g: &mut Gen) -> Self {{ match g.below({}) {{",
                def.name,
                def.branches.len()
            );
            for (index, branch) in def.branches.iter().enumerate() {
                let pattern = if index + 1 == def.branches.len() { "_".to_owned() } else { index.to_string() };
                match &branch.ty {
                    Ty::Unit => {
                        let _ = writeln!(out, "{pattern} => Self::{},", branch.name);
                    }
                    ty => {
                        let _ = writeln!(out, "{pattern} => Self::{}({}),", branch.name, self.sample(ty));
                    }
                }
            }
            out.push_str("} } }\n");
        }
        for packet in &model.packets {
            let _ = writeln!(
                out,
                "impl Sample for {} {{ fn sample(g: &mut Gen) -> Self {{ Self {{ payload: {} }} }} }}",
                packet.name,
                self.sample(&packet.payload)
            );
        }
        out.push_str(&raw_doc("Pseudo-random packet for this identifier."));
        out.push_str("pub fn sample_packet(packet_id: u32, g: &mut Gen) -> Option<Packet> { match packet_id {\n");
        for packet in &model.packets {
            let _ = writeln!(out, "{}::ID => Some(Packet::{}(Sample::sample(g))),", packet.name, packet.variant);
        }
        out.push_str("_ => None,\n} }\n");
        out
    }
}

/// Tests shipped with the generated code: they run against whatever protocol
/// version was generated, without naming any specific packet.
const MODULE_TESTS: &str = r#"
#[cfg(test)]
mod tests {
    use super::packets::Packet;
    use super::samples::sample_packet;
    use crate::codec::{PacketHeader, ProtocolError};
    use crate::testing::Gen;

    #[test]
    fn packet_ids_are_sorted_and_unique() {
        assert_eq!(Packet::IDS.len(), super::PACKET_COUNT);
        assert!(Packet::IDS.windows(2).all(|pair| pair[0] < pair[1]));
        for &id in Packet::IDS {
            let packet = Packet::default_for_id(id).expect("every listed id has a packet");
            assert_eq!(packet.packet_id(), id);
            assert_eq!(Packet::name_of(id), Some(packet.name()));
        }
    }

    #[test]
    fn unknown_packet_id_is_an_error() {
        let unknown = Packet::IDS.iter().max().unwrap() + 1;
        assert!(Packet::default_for_id(unknown).is_none());
        assert_eq!(Packet::decode(unknown, &mut [].as_slice()), Err(ProtocolError::UnknownPacketId(unknown)));
    }

    #[test]
    fn default_packets_round_trip() {
        for &id in Packet::IDS {
            let packet = Packet::default_for_id(id).unwrap();
            let mut bytes = Vec::new();
            packet.encode(&mut bytes).unwrap_or_else(|e| panic!("encoding {}: {e}", packet.name()));
            let mut slice = bytes.as_slice();
            let decoded = Packet::decode(id, &mut slice).unwrap_or_else(|e| panic!("decoding {}: {e}", packet.name()));
            assert!(slice.is_empty(), "{} left {} byte(s) unread", packet.name(), slice.len());
            assert_eq!(decoded, packet, "{}", packet.name());
        }
    }

    #[test]
    fn sampled_packets_round_trip() {
        for seed in 0..16u64 {
            for &id in Packet::IDS {
                let mut gen = Gen::new(seed.wrapping_mul(0x9e37_79b9).wrapping_add(id as u64));
                let packet = sample_packet(id, &mut gen).unwrap();
                let mut bytes = Vec::new();
                packet.encode(&mut bytes).unwrap_or_else(|e| panic!("encoding {}: {e}", packet.name()));
                let mut slice = bytes.as_slice();
                let decoded =
                    Packet::decode(id, &mut slice).unwrap_or_else(|e| panic!("decoding {} (seed {seed}): {e}", packet.name()));
                assert!(slice.is_empty(), "{} left {} byte(s) unread (seed {seed})", packet.name(), slice.len());
                assert_eq!(decoded, packet, "{} (seed {seed})", packet.name());
            }
        }
    }

    #[test]
    fn header_round_trip() {
        for &id in Packet::IDS {
            let packet = Packet::default_for_id(id).unwrap();
            let mut bytes = Vec::new();
            packet.encode_with_header(&mut bytes).unwrap();
            let (header, decoded) = Packet::decode_with_header(&mut bytes.as_slice()).unwrap();
            assert_eq!(header, PacketHeader::new(id));
            assert_eq!(decoded, packet);
        }
    }

    #[test]
    fn truncated_input_never_panics() {
        for &id in Packet::IDS {
            let mut gen = Gen::new(0xbed0_0000 + id as u64);
            let packet = sample_packet(id, &mut gen).unwrap();
            let mut bytes = Vec::new();
            packet.encode(&mut bytes).unwrap();
            for len in 0..bytes.len().min(96) {
                // Must return (an error or a shorter valid packet), not panic.
                let _ = Packet::decode(id, &mut &bytes[..len]);
            }
        }
    }
}
"#;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn docs_are_made_safe_for_rustdoc() {
        let attrs = doc_attrs(Some("First\n\t\t\t\tindented `code` [link] <tag>\n```rust"));
        let lines: Vec<&str> = attrs.lines().collect();
        assert_eq!(lines[0], r#"#[doc = " First"]"#);
        assert_eq!(lines[1], r#"#[doc = " indented `code` \\[link\\] \\<tag\\>"]"#);
        assert_eq!(lines[2], r#"#[doc = " '''rust"]"#);
        assert_eq!(doc_attrs(None), "");
    }

    #[test]
    fn deref_strips_a_single_reference() {
        assert_eq!(deref("&self.x"), "self.x");
        assert_eq!(deref("v0"), "*v0");
        assert_eq!(deref("&**(v0)"), "**(v0)");
    }

    #[test]
    fn invalid_rust_is_reported() {
        assert!(format_file("pub struct {", "x.rs").is_err());
        assert!(format_file("pub struct A;", "x.rs").unwrap().starts_with("// @generated"));
    }
}
